REMOVED = ['Kennedy1995', 'Storn1997', 'Mirjalili2014', 'Satapathy2016', 'Naik2020', 'Katoch2021']   # optimiser-only references, kept in the supplement
order = []
def cite(text):
    def rep(m):
        keys = [k.strip() for k in m.group(1).split(',')]
        for k in keys:
            assert k in REFS.index and k not in REMOVED, k
            if k not in order: order.append(k)
        return '[' + ', '.join(str(n) for n in sorted(order.index(k) + 1 for k in keys)) + ']'
    return re.sub(r'(?<![\^_])\{([A-Za-z][A-Za-z0-9_, ]*)\}', rep, text)
B = []; LAB = {}; CNT = {'T': 0, 'F': 0}
def T(k): return f'@T:{k}@'
def F(k): return f'@F:{k}@'
def add(t, text=None, **kw): B.append({'type': t, **({'text': cite(text)} if text is not None else {}), **kw})
def para(t): add('para', t)
def bullet(t): add('bullet', t)
def aspect(png):
    from PIL import Image
    w, h = Image.open(png).size; return h / w
def table(key, caption, header, rows, widths, note=None, size=15):
    CNT['T'] += 1; LAB[f'T:{key}'] = CNT['T']; B.append({'type': 'caption', 'text': cite(f'**Table {CNT["T"]}.** {caption}'), 'keepNext': True})
    B.append({'type': 'table', 'header': header, 'rows': [[cite(str(c)) for c in r] for r in rows], 'widths': widths, 'note': cite(note) if note else None, 'size': size})
def figure(key, path, caption, width=620):
    CNT['F'] += 1; LAB[f'F:{key}'] = CNT['F']; B.append({'type': 'figure', 'path': str(path), 'aspect': aspect(path), 'alt': caption[:90], 'width_px': width})
    B.append({'type': 'caption', 'text': cite(f'**Figure {CNT["F"]}.** {caption}')})

