    rows.append([r.Disease, r.Model.replace(' Rank average', '').replace(' Inner-selected single', ''), f'{rc(r.Disease, r.Model):.3f}', r['ROC-AUC fold mean (SD)'], r['ROC-AUC pooled [95% CI]'],
                 w['Within-year AUC pooled [95% CI]'], r['PR-AUC (no-skill)'], f"{r['MCC']:.2f}"])
